import os
import subprocess

from anthropic import Anthropic

client = Anthropic()

CHILD_ENV_ALLOWLIST = ("PATH", "HOME", "LANG", "TZ")


def mint_token(ttl_seconds: int) -> str:
    """Ask the broker for a task-scoped credential that expires by itself."""
    return _broker.issue(ttl_seconds=ttl_seconds, scope="read:repo")


def _child_env() -> dict:
    base = {k: os.environ[k] for k in CHILD_ENV_ALLOWLIST if k in os.environ}
    base["TASK_TOKEN"] = mint_token(ttl_seconds=300)
    return base


def run_shell(command: str) -> str:
    proc = subprocess.run(
        command,
        shell=True,
        capture_output=True,
        text=True,
        env=_child_env(),
    )
    return proc.stdout + proc.stderr


def step(goal: str) -> str:
    msg = client.messages.create(
        model="claude-sonnet-4-5",
        max_tokens=1024,
        messages=[{"role": "user", "content": goal}],
    )
    return run_shell(msg.content[0].text)
